/**
 * The parity proof of the members-only object locator (kind 65, `./members-index`): every
 * `members_index__` vector in `forge-contracts/vectors/` (generated by
 * `tools/private-repos-vectors/members_git.py`), run against the web's encoder and parser.
 * forge-core `members_git::conformance` runs the same files, with the same input and output shapes.
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { bytesToHex, hexToBytes } from '@noble/hashes/utils.js'
import { describe, expect, it } from 'vitest'

import { ObjectLocator } from './locator'
import { encodeMembersIndex, parseMembersIndex } from './members-index'

interface Vector {
  readonly name: string
  readonly case: string
  readonly input: { readonly op: string; readonly packHash?: string; readonly locator?: string; readonly bytes?: string }
  readonly expected: unknown
}

const VECTORS_DIR = resolve(process.cwd(), '..', 'forge-contracts', 'vectors')
const FILES = readdirSync(VECTORS_DIR)
  .filter((f) => f.startsWith('members_index__') && f.endsWith('.json'))
  .sort()
/** The input keys forge-core's `MembersIndexIn` accepts (`deny_unknown_fields`). */
const INPUT_KEYS = new Set(['op', 'packHash', 'locator', 'bytes'])

function run(v: Vector): unknown {
  const i = v.input
  if (i.op === 'encode') {
    const locator = ObjectLocator.parse(hexToBytes(i.locator as string))
    try {
      return { bytes: bytesToHex(encodeMembersIndex(hexToBytes(i.packHash as string), locator)) }
    } catch {
      return { error: 'malformed' }
    }
  }
  if (i.op === 'parse') {
    try {
      const parsed = parseMembersIndex(hexToBytes(i.bytes as string))
      return parsed === null ? { skip: true } : { packHash: parsed.packHash, objectCount: parsed.locator.count }
    } catch {
      return { error: 'malformed' }
    }
  }
  throw new Error(`vector ${v.name}: op ${i.op}`)
}

describe('members_index conformance (forge-contracts/vectors)', () => {
  it('finds the vectors', () => {
    expect(FILES.length).toBeGreaterThanOrEqual(9)
  })

  for (const file of FILES) {
    it(file, () => {
      const v = JSON.parse(readFileSync(resolve(VECTORS_DIR, file), 'utf8')) as Vector
      expect(v.case).toBe('members_index')
      for (const k of Object.keys(v.input)) expect(INPUT_KEYS.has(k), `${file}: input key ${k}`).toBe(true)
      expect(run(v)).toEqual(v.expected)
    })
  }
})
